{
  "passages": [
    {
      "id": "m51",
      "about_topic": true,
      "says": "fact: motorcycles, bicycles, etc. often pull to the side to avoid hazards or be seen; rule: do not pass in the same lane; rule: pass these vehicles by changing lanes"
    },
    {
      "id": "m1",
      "about_topic": true,
      "says": "fact: changing position involves changing lanes or overtaking/passing"
    },
    {
      "id": "m4",
      "about_topic": true,
      "says": "rule: ensure enough space and time to complete the move safely before beginning"
    },
    {
      "id": "m2",
      "about_topic": true,
      "says": "definition: passing is changing lanes to move past a slower vehicle"
    },
    {
      "id": "m3",
      "about_topic": true,
      "says": "fact: not all vehicles travel at the same speed; examples of slower vehicles; fact: a driver may want to pass slow-moving vehicles when following them"
    },
    {
      "id": "m5",
      "about_topic": true,
      "says": "rule: never overtake and pass unless sure it can be done without danger"
    },
    {
      "id": "m72",
      "about_topic": true,
      "says": "rule: do not pass moving snow plows under any conditions"
    },
    {
      "id": "m6",
      "about_topic": true,
      "says": "rule: if in doubt, do not pass"
    },
    {
      "id": "m8",
      "about_topic": true,
      "says": "lead: steps for passing a vehicle"
    },
    {
      "id": "m9",
      "about_topic": true,
      "says": "procedure step: use left-turn signal, check way is clear ahead and behind before moving into passing lane"
    },
    {
      "id": "m10",
      "about_topic": true,
      "says": "procedure step: watch for hidden bicycles/small vehicles, turning vehicles, and vehicles/pedestrians entering the road"
    },
    {
      "id": "m11",
      "about_topic": true,
      "says": "procedure step: change lanes only after signalling; after overtaking, signal to move back; change lanes when entire front of vehicle is visible in inside mirror"
    },
    {
      "id": "m12",
      "about_topic": true,
      "says": "rule: do not cut off a vehicle by suddenly moving in front of it"
    },
    {
      "id": "m13",
      "about_topic": true,
      "says": "rule: if the vehicle being passed speeds up, do not race; go back to original lane"
    },
    {
      "id": "m85",
      "about_topic": true,
      "says": "rule: do not speed up when another driver is trying to pass; it is unlawful and dangerous"
    },
    {
      "id": "m14",
      "about_topic": true,
      "says": "figure: diagram of how to pass another vehicle"
    },
    {
      "id": "m15",
      "about_topic": true,
      "says": "rule: passing within 30 m of a pedestrian crossover is not permitted"
    },
    {
      "id": "m17",
      "about_topic": true,
      "says": "rule: passing left of a centreline is not permitted 30 m from a bridge, viaduct or tunnel"
    },
    {
      "id": "m18",
      "about_topic": true,
      "says": "rule: do not attempt to pass when approaching crest of hill or on curve with obstructed vision and insufficient clear distance"
    },
    {
      "id": "m50",
      "about_topic": true,
      "says": "rule: when passing parked vehicles, watch for people opening doors or doors opened to load/unload"
    },
    {
      "id": "m84",
      "about_topic": true,
      "says": "rule: when faster traffic wants to pass, move to the right and let it pass in safety"
    },
    {
      "id": "m89",
      "about_topic": true,
      "says": "rule: when being passed on an undivided road, pay attention to oncoming traffic, move closer to right side, be prepared to slow down"
    },
    {
      "id": "m90",
      "about_topic": true,
      "says": "fact: on many high-speed roads, trucks are not allowed in far left lane; the next lane is the truck passing lane; rule: if in this lane and a truck wants to pass, move to right-hand lane as soon as possible"
    },
    {
      "id": "m52",
      "about_topic": true,
      "says": "figure: diagram of how to pass another vehicle"
    },
    {
      "id": "m39",
      "about_topic": true,
      "says": "rule: be very careful when passing other vehicles at night"
    },
    {
      "id": "m40",
      "about_topic": true,
      "says": "lead: steps for passing at night when the way is clear"
    },
    {
      "id": "m41",
      "about_topic": true,
      "says": "procedure step: switch headlights to low beams as you approach a vehicle from behind"
    },
    {
      "id": "m42",
      "about_topic": true,
      "says": "procedure step: signal, check mirrors and blind spot, pull out to pass; switch on high beams when moving alongside"
    },
    {
      "id": "m43",
      "about_topic": true,
      "says": "procedure step: when front of vehicle is visible in rear view mirror, pull back into right lane; remember to signal"
    },
    {
      "id": "m27",
      "about_topic": true,
      "says": "figure: diagram of a passing or climbing lane"
    },
    {
      "id": "m28",
      "about_topic": true,
      "says": "fact: some roads have special passing or climbing lanes that let slower vehicles move right so faster ones can pass safely in the left lane"
    },
    {
      "id": "m29",
      "about_topic": true,
      "says": "fact: an advance sign tells drivers they will soon have a chance to pass; another sign warns when the lane is ending so drivers can merge safely"
    },
    {
      "id": "m38",
      "about_topic": true,
      "says": "rule: may drive on right shoulder only to pass a vehicle turning left and only if paved; may not pass on left shoulder"
    },
    {
      "id": "m35",
      "about_topic": true,
      "says": "fact: most passing is done on the left; rule: may pass on right on multi-lane or one-way roads and when overtaking a streetcar or left-turning vehicle"
    },
    {
      "id": "m36",
      "about_topic": true,
      "says": "fact: passing on the right can be more dangerous than passing on the left"
    },
    {
      "id": "m37",
      "about_topic": true,
      "says": "rule: if in left most lane with slower vehicle ahead, wait for vehicle to move right; do not suddenly change lanes and pass on right"
    },
    {
      "id": "m61",
      "about_topic": true,
      "says": "figure: diagram of a vehicle stopped 2 m behind rear doors of a stopped streetcar"
    },
    {
      "id": "m62",
      "about_topic": true,
      "says": "rule: must pass streetcars on the right unless driving on a one-way road"
    },
    {
      "id": "m63",
      "about_topic": true,
      "says": "rule: at streetcar stops, stay at least 2 m behind rear doors where passengers are getting off/on; exception: does not apply at stops with area set aside for passengers"
    },
    {
      "id": "m64",
      "about_topic": true,
      "says": "rule: always pass these areas at a reasonable speed and be prepared for pedestrians to make sudden or unexpected moves"
    }
